    virtual bool GetDisplay() const;
};

extern float WAVE_GetHeightFudgeFactor(int);
extern int WAVE_GetScheduleIndex();
extern int WAVE_GetNextScheduleIndex();
__asm__(".equ WAVE_GetHeightFudgeFactor__Fi, 0x0037DCE8");
__asm__(".equ WAVE_GetScheduleIndex__Fv, 0x0037D8B8");
__asm__(".equ WAVE_GetNextScheduleIndex__Fv, 0x0037D8C8");

class WaveIndicatorWidget : public IGOWidget {
public:
    enum STATE { STATE_NONE, STATE_DIR, STATE_SURGE, STATE_TONGUE, STATE_HILITE_NONE, STATE_HILITE_FACE, STATE_HILITE_LIP, STATE_HILITE_TUBE };
private:
    PanelQuad *wavePQ[2][3];
    PanelQuad *arrowPQ[2];
    PanelQuad *tonguePQ[2][6];
    PanelQuad *hilitePQ[2][3];
    PanelQuad *heightPQ;
    TextString *heightText;
    TextString *unitText;
    TextString *nextHeightText;
    TextString *nextUnitText;
    int dirIdx;
    float waveIdx;
    float tongueIdx;
    float hiliteTime;
    float fade;
    int fadeDir;
    STATE state;
public:
    void ShowDirection(bool, float, float) __asm__("ShowDirection__19WaveIndicatorWidgetbff");
};

void WaveIndicatorWidget::ShowDirection(const bool fadeIn, const float waveHeight, const float nextWaveHeight)
{
    stringx s;

    if (fadeIn)
    {
        fade = 0.0f;
        fadeDir = 1;
    }
    else
    {
        fade = 1.0f;
        fadeDir = 0;
    }

    float wave_scale = 1.0f;
    float next_wave_scale = 1.0f;

    wave_scale = WAVE_GetHeightFudgeFactor(WAVE_GetScheduleIndex());
    next_wave_scale = WAVE_GetHeightFudgeFactor(WAVE_GetNextScheduleIndex());

    s.printf("%.1f", waveHeight*3.28084f*wave_scale);
    heightText->changeText(s);
    s.printf("%.1f", nextWaveHeight*3.28084f*next_wave_scale);
    nextHeightText->changeText(s);

    waveIdx = 0;
    tongueIdx = 0;
    state = STATE_DIR;
}
